439: void ui_event_mouse_func( int button, int state, int x, int y )
440: {
441:     if ( is_mode_change_pending() ) {
442: 	/* Don't process events until mode change occurs */
443: 	return;
444:     }
445: 
446:     /* Reverse y coordinate */
447:     y = getparam_y_resolution() - y;
448: 
449:     if ( state == WS_MOUSE_DOWN ) {
450: 	trigger_mouse_button_cbs( mouse_down_cbs, button, x, y );
451:     } else {
452: 	trigger_mouse_button_cbs( mouse_up_cbs, button, x, y );
453:     }
454: 
455:     if ( button == WS_LEFT_BUTTON ) {
456: 	left_mouse_button_down = (bool_t) ( state == WS_MOUSE_DOWN );
457:     }
458:     if ( button == WS_MIDDLE_BUTTON ) {
459: 	middle_mouse_button_down = (bool_t) ( state == WS_MOUSE_DOWN );
460:     }
461:     if ( button == WS_RIGHT_BUTTON ) {
462: 	right_mouse_button_down = (bool_t) ( state == WS_MOUSE_DOWN );
463:     }
464: 
465:     ui_check_dirty();
466: }
