477: void ui_event_motion_func( int x, int y )
478: {
479:     point2d_t old_pos;
480: 
481:     if ( is_mode_change_pending() ) {
482: 	/* Don't process events until mode change occurs */
483: 	return;
484:     }
485: 
486:     /* Reverse y coordinate */
487:     y = getparam_y_resolution() - y;
488: 
489:     trigger_mouse_motion_cbs( mouse_motion_cbs, x, y );
490: 
491:     old_pos = cursor_pos;
492:     cursor_pos = make_point2d( x, y );
493: 
494:     if ( old_pos.x != x || old_pos.y != y ) {
495: 	/* Update UI snow */
496: 	if ( getparam_ui_snow() ) {
497: 	    if ( right_mouse_button_down ) {
498: 		make_ui_snow( cursor_pos );
499: 		reset_ui_snow_cursor_pos( cursor_pos );
500: 	    } else if ( middle_mouse_button_down ) {
501: 		make_ui_snow( cursor_pos );
502: 		push_ui_snow( cursor_pos );
503: 	    } else {
504: 		push_ui_snow( cursor_pos );
505: 	    }
506: 	}
507: 
508: 	/* Need to redraw cursor */
509: 	ui_set_dirty();
510: 	ui_check_dirty();
511:     }
